import { describe, it, expect } from "vitest";
import { join, dirname } from "path";
import { fileURLToPath } from "url";
import {
  parseCargoLock,
  parseGoMod,
  parseGemfileLock,
  parseComposerLock,
  parseOtherEcosystems,
} from "../parsers/other-locks.js";
import { getFixedVersion, planUpgrade } from "../fix.js";
import type { Dependency } from "../parsers/npm.js";

// Fixtures were generated by the real tools in their official Docker images:
//   cargo generate-lockfile (rust:1-slim)   chrono 0.4.19 + smallvec 1.6.0, dev tempfile 3.2.0
//   go mod tidy (golang:1.23)               golang.org/x/net v0.10.0
//   bundle lock (ruby:3.3-slim)             actionpack 6.1.0 + rack 2.2.3, development rspec 3.10.0
//   composer update --no-install (composer:2) symfony/http-kernel 4.4.0, dev phpunit 9.5.0
const FIXTURES = join(dirname(fileURLToPath(import.meta.url)), "fixtures", "lockfiles");

function byKey(deps: Dependency[]): Record<string, { dev: boolean; path?: string }> {
  return Object.fromEntries(
    deps.map((d) => [`${d.name}@${d.version}`, { dev: d.isDev, ...(d.path ? { path: d.path.join(" > ") } : {}) }])
  );
}

describe("real lockfiles", () => {
  it("detects every ecosystem with its OSV name and source file", () => {
    const found = ["cargo", "go", "ruby", "composer"].flatMap((d) => parseOtherEcosystems(join(FIXTURES, d)));
    expect(found.map((f) => [f.ecosystem, f.deps.length, f.deps[0]!.file])).toEqual([
      ["crates.io", 28, "Cargo.lock"],
      ["Go", 1, "go.mod"],
      ["RubyGems", 26, "Gemfile.lock"],
      ["Packagist", 48, "composer.lock"],
    ]);
  });

  it("Cargo: workspace crate is not audited; dev subtree from Cargo.toml; shared crates stay production", () => {
    const deps = byKey(parseOtherEcosystems(join(FIXTURES, "cargo"))[0]!.deps);
    expect(deps["fx@0.1.0"]).toBeUndefined();
    expect(deps["time@0.1.45"]).toEqual({ dev: false, path: "chrono@0.4.19 > time@0.1.45" });
    expect(deps["tempfile@3.2.0"]).toEqual({ dev: true, path: "tempfile@3.2.0" });
    expect(deps["rand@0.8.8"]!.dev).toBe(true);
    expect(deps["libc@0.2.190"]!.dev).toBe(false); // used by chrono and tempfile
    // two wasi releases, resolved by "name version" references
    expect(deps["wasi@0.10.0+wasi-snapshot-preview1"]!.dev).toBe(false);
    expect(deps["wasi@0.11.1+wasi-snapshot-preview1"]!.dev).toBe(true);
  });

  it("Ruby: platform builds merge into one release; Gemfile groups mark dev gems", () => {
    const deps = byKey(parseOtherEcosystems(join(FIXTURES, "ruby"))[0]!.deps);
    expect(Object.keys(deps).filter((k) => k.startsWith("nokogiri@"))).toEqual(["nokogiri@1.19.4"]);
    expect(deps["rack@2.2.3"]).toEqual({ dev: false, path: "rack@2.2.3" });
    expect(deps["rspec-core@3.10.2"]).toEqual({ dev: true, path: "rspec@3.10.0 > rspec-core@3.10.2" });
    expect(deps["nokogiri@1.19.4"]!.path).toBe("actionpack@6.1.0 > rails-dom-testing@2.3.0 > nokogiri@1.19.4");
  });

  it("Composer: packages-dev are dev; platform requirements are ignored", () => {
    const deps = byKey(parseOtherEcosystems(join(FIXTURES, "composer"))[0]!.deps);
    expect(deps["symfony/http-kernel@v4.4.0"]).toEqual({ dev: false, path: "symfony/http-kernel@v4.4.0" });
    expect(deps["phpunit/phpunit@9.5.0"]!.dev).toBe(true);
    expect(deps["psr/log@1.1.4"]!.path).toBe("symfony/http-kernel@v4.4.0 > psr/log@1.1.4");
    expect(Object.keys(deps).some((k) => k.startsWith("php@") || k.startsWith("ext-"))).toBe(false);
  });
});

describe("go.mod", () => {
  const gomod = `module example.com/app

go 1.22

toolchain go1.22.5

require github.com/single/dep v1.0.0

require (
	golang.org/x/net v0.10.0
	golang.org/x/text v0.9.0 // indirect
	example.com/forked v1.2.0
	example.com/local v0.0.0
	github.com/pseudo/mod v0.0.0-20210101000000-abcdef123456 // indirect
)

replace example.com/forked v1.2.0 => github.com/me/forked v1.2.1

replace example.com/local => ../local
`;

  it("reads single and block requires; only direct modules get a path", () => {
    expect(byKey(parseGoMod(gomod))).toEqual({
      "github.com/single/dep@v1.0.0": { dev: false, path: "github.com/single/dep@v1.0.0" },
      "golang.org/x/net@v0.10.0": { dev: false, path: "golang.org/x/net@v0.10.0" },
      "golang.org/x/text@v0.9.0": { dev: false },
      "github.com/me/forked@v1.2.1": { dev: false, path: "github.com/me/forked@v1.2.1" },
      "github.com/pseudo/mod@v0.0.0-20210101000000-abcdef123456": { dev: false },
    });
  });
});

describe("Cargo.lock edge cases", () => {
  it("skips git sources and resolves bare and versioned references", () => {
    const deps = parseCargoLock(`version = 3

[[package]]
name = "app"
version = "0.1.0"
dependencies = ["serde", "rand 0.8.5", "patched"]

[[package]]
name = "serde"
version = "1.0.0"
source = "sparse+https://index.crates.io/"

[[package]]
name = "rand"
version = "0.8.5"
source = "registry+https://github.com/rust-lang/crates.io-index"

[[package]]
name = "rand"
version = "0.7.3"
source = "registry+https://github.com/rust-lang/crates.io-index"

[[package]]
name = "patched"
version = "0.2.0"
source = "git+https://github.com/x/patched?rev=abc#abc"
`);
    expect(byKey(deps)).toEqual({
      "serde@1.0.0": { dev: false, path: "serde@1.0.0" },
      "rand@0.8.5": { dev: false, path: "rand@0.8.5" },
      "rand@0.7.3": { dev: false },
    });
  });
});

describe("Gemfile.lock edge cases", () => {
  it("skips GIT/PATH gems and reads inline group: options", () => {
    const lock = `GIT
  remote: https://github.com/x/forked.git
  revision: abc
  specs:
    forked (1.0.0)

GEM
  remote: https://rubygems.org/
  specs:
    pry (0.14.0)
    rails (7.0.0)

PLATFORMS
  ruby

DEPENDENCIES
  forked!
  pry
  rails (~> 7.0)
`;
    const gemfile = `source "https://rubygems.org"
gem "rails", "~> 7.0"
gem "pry", group: :development
gem "forked", git: "https://github.com/x/forked.git"
`;
    expect(byKey(parseGemfileLock(lock, gemfile))).toEqual({
      "pry@0.14.0": { dev: true, path: "pry@0.14.0" },
      "rails@7.0.0": { dev: false, path: "rails@7.0.0" },
    });
  });

  it("a gem in both a dev group and the default group is production", () => {
    const lock = "GEM\n  specs:\n    json (2.0.0)\n\nDEPENDENCIES\n  json\n";
    const gemfile = 'gem "json"\ngroup :test do\n  gem "json"\nend\n';
    expect(parseGemfileLock(lock, gemfile)[0]!.isDev).toBe(false);
  });
});

describe("composer.lock edge cases", () => {
  it("skips dev-branch versions", () => {
    const deps = parseComposerLock(
      JSON.stringify({ packages: [{ name: "a/b", version: "dev-main" }, { name: "c/d", version: "v1.0.0", require: { php: ">=8", "ext-json": "*" } }] })
    );
    expect(byKey(deps)).toEqual({ "c/d@v1.0.0": { dev: false } });
  });
});

describe("fix versions keep the installed version style", () => {
  it("adds the v prefix that Go and Composer use", () => {
    const vuln = { id: "GO-1", affected: [{ package: { name: "golang.org/x/net", ecosystem: "Go" }, ranges: [{ type: "SEMVER", events: [{ introduced: "0" }, { fixed: "0.38.0" }] }] }] };
    expect(getFixedVersion(vuln, "golang.org/x/net", "v0.10.0", "Go")).toBe("v0.38.0");
    expect(planUpgrade({ name: "golang.org/x/net", version: "v0.10.0", ecosystem: "Go", vulns: [vuln] }).version).toBe("v0.38.0");
    expect(getFixedVersion(vuln, "golang.org/x/net", "0.10.0", "Go")).toBe("0.38.0");
  });
});
